import { readFile, writeFile } from 'node:fs/promises';
const source = JSON.parse(await readFile(new URL('../backend/knowledge.json', import.meta.url), 'utf8'));
// Publish only approved answers and exact preview questions; never system rules or secrets.
const preview = {
  greeting: source.greeting,
  thanks: source.thanks,
  fallback: source.previewFallback,
  answers: source.answers.map(({ answer, previewQuestions }) => ({ answer, questions: previewQuestions })),
};
await writeFile(new URL('../website/chatbot-preview.js', import.meta.url),
  '/* Generated by npm run sync-preview. Public, approved preview answers only. */\nwindow.PORTFOLIO_CHAT_PREVIEW = ' +
  JSON.stringify(preview, null, 2).replace(/</g, '\\u003c') + ';\n');
console.log('Updated public saved-answer preview.');
